def count_squares(lines):
    def find_corners(line):
        return [i for i, char in enumerate(line) if char == '+']

    def is_corner(x, y):
        return lines[y][x] == '+'

    def is_horizontal_edge(x1, y, x2):
        return all(lines[y][i] == '-' for i in range(x1, x2 + 1))

    def is_vertical_edge(y1, x, y2):
        return all(lines[i][x] == '|' for i in range(y1, y2 + 1))

    def is_square(x1, y1, side_length):
        for i in range(side_length):
            if not (is_horizontal_edge(x1, y1 + i, x1 + side_length - 1) and
                    is_horizontal_edge(x1 + i, y1, x1 + side_length - 1)):
                return False
        for j in range(side_length):
            if not (is_vertical_edge(y1 + j, x1, y1 + side_length - 1) and
                    is_vertical_edge(y1, x1 + j, y1 + side_length - 1)):
                return False
        return True

    def count_squares_in_rectangle(x1, y1, x2, y2):
        count = 0
        side_length = min(x2 - x1 + 1, y2 - y1 + 1)
        for size in range(2, side_length):
            if is_square(x1, y1, size):
                count += 1
        return count

    corners = []
    for y, line in enumerate(lines):
        corners.extend((x, y) for x in find_corners(line))

    total_squares = 0
    for i in range(len(corners)):
        x1, y1 = corners[i]
        for j in range(i + 1, len(corners)):
            x2, y2 = corners[j]
            if x1 <= x2 and y1 <= y2:
                total_squares += count_squares_in_rectangle(x1, y1, x2, y2)

    return total_squares

